shell_commands:
cat > /tmp/probe-onError.test.ts <<'EOF'
import {createChatOrchestrator} from './chatOrchestrator.js';
import type {OrchestratorHooks} from './chatOrchestrator.js';
import type {AIProvider, MessageChunk, SendMessageParams} from '../types/ai.js';
import type {ChatSession} from '../types/session.js';
import {PromptBuilder} from '../infrastructure/builders/promptBuilder.js';

const promptBuilder = new PromptBuilder({identity: 'probe'});

const rejectingProvider = (value: unknown): AIProvider => ({
  // eslint-disable-next-line require-yield
  async *sendMessage(): AsyncGenerator<MessageChunk> {
    throw value;
  },
  async generateStructured<T>(): Promise<T> {
    return {} as T;
  },
});

describe('probe', () => {
  it('reports what happens on a string rejection', async () => {
    const calls: unknown[] = [];
    const hooks: OrchestratorHooks = {onError: async (_s, e) => void calls.push(e)};
    const orchestrator = createChatOrchestrator(rejectingProvider('kaboom-string'), promptBuilder, undefined, {hooks});
    const session: ChatSession = {sessionId: 's', userId: 'u', entries: []};
    let rejected: unknown;
    try {
      await orchestrator.processMessage(session);
    } catch (e) {
      rejected = e;
    }
    process.stdout.write(
      `PROBE onError calls: ${calls.length}, types: ${calls.map(c => (c instanceof Error ? 'Error' : typeof c))}\n`
    );
    process.stdout.write(`PROBE caller received: ${typeof rejected} ${String(rejected)}\n`);
    process.stdout.write(
      `PROBE instanceof check: ${String(rejected instanceof Error)}, cause: ${(rejected as Error)?.cause}\n`
    );
  });
});
EOF
mkdir -p /tmp/probe-run && cp /tmp/probe-onError.test.ts src/orchestration/zz-probe.test.ts && node --experimental-vm-modules node_modules/jest/bin/jest.js --runTestsByPath src/orchestration/zz-probe.test.ts 2>&1 | tail -15; rm src/orchestration/zz-probe.test.ts
